import math

def build_agent(sandbox):
    return {
        'state': {
            'activated': False,
            'activation_count': 0,
            'rendezvous1_done': False,
            'rendezvous2_done': False,
            'cooldown_remaining': 0,
            'target_positions': [],
            'seeker_angle': 0.0,
            'seeker_pos': (14.0, 1.35),
            'target_velocity': (0.0, 0.0)
        }
    }

def agent_action(sandbox, agent_body, step_count):
    state = agent_body.get('state', {})

    # Get seeker state
    seeker_pos = sandbox.get_seeker_position()
    seeker_vel = sandbox.get_seeker_velocity()
    seeker_angle = sandbox.get_seeker_heading()

    # Get target state
    target_pos = sandbox.get_target_position()
    state['target_positions'].append(target_pos)
    if len(state['target_positions']) > 10:
        state['target_positions'].pop(0)

    # Calculate target velocity
    target_vel = (0.0, 0.0)
    if len(state['target_positions']) >= 2:
        prev_pos = state['target_positions'][-2]
        current_pos = state['target_positions'][-1]
        dx = current_pos[0] - prev_pos[0]
        dy = current_pos[1] - prev_pos[1]
        target_vel = (dx, dy)

    # Determine target direction for heading alignment
    target_speed = math.hypot(target_vel[0], target_vel[1])
    if target_speed >= 0.15:
        # Target is moving, align with velocity direction
        target_dir = (target_vel[0], target_vel[1])
        target_dir_length = math.hypot(target_dir[0], target_dir[1])
        if target_dir_length > 0:
            target_dir = (target_dir[0]/target_dir_length, target_dir[1]/target_dir_length)
            desired_angle = math.atan2(target_dir[1], target_dir[0])
        else:
            desired_angle = seeker_angle
    else:
        # Target is not moving, align with seeker-to-target direction
        dx = target_pos[0] - seeker_pos[0]
        dy = target_pos[1] - seeker_pos[1]
        desired_angle = math.atan2(dy, dx)

    # Activation phase
    if not state['activated']:
        x = seeker_pos[0]
        if 13.0 <= x <= 17.0:
            state['activation_count'] += 1
        else:
            state['activation_count'] = 0
        if state['activation_count'] >= 80:
            state['activated'] = True
        # Adjust heading to stay in activation zone if not activated
        if not state['activated']:
            if x < 13.0:
                # Move right
                desired_angle = math.atan2(0, 1)  # East direction
            elif x > 17.0:
                # Move left
                desired_angle = math.atan2(0, -1)  # West direction
            else:
                desired_angle = seeker_angle
            # Adjust heading to desired_angle, within max rotation rate
            current_angle = seeker_angle
            diff = desired_angle - current_angle
            diff = diff % (2 * math.pi)
            if diff > math.pi:
                diff = 2 * math.pi - diff
            if abs(diff) > 0.12:
                if diff > 0:
                    new_angle = current_angle + 0.12
                else:
                    new_angle = current_angle - 0.12
            else:
                new_angle = current_angle
            state['seeker_angle'] = new_angle
    else:
        # Check if in rendezvous slots
        slots = sandbox.get_rendezvous_slots()
        for slot in slots:
            if slot[0] <= step_count <= slot[1]:
                # First rendezvous
                if not state['rendezvous1_done']:
                    dx = target_pos[0] - seeker_pos[0]
                    dy = target_pos[1] - seeker_pos[1]
                    distance = math.hypot(dx, dy)
                    relative_speed = math.hypot(target_vel[0] - seeker_vel[0], target_vel[1] - seeker_vel[1])
                    if distance <= 6.0 and relative_speed < 1.8 and abs(desired_angle - seeker_angle) <= math.radians(55):
                        state['rendezvous1_done'] = True
                # Second rendezvous
                elif not state['rendezvous2_done']:
                    dx = target_pos[0] - seeker_pos[0]
                    dy = target_pos[1] - seeker_pos[1]
                    distance = math.hypot(dx, dy)
                    relative_speed = math.hypot(target_vel[0] - seeker_vel[0], target_vel[1] - seeker_vel[1])
                    if distance <= 6.0 and relative_speed < 1.8 and abs(desired_angle - seeker_angle) <= math.radians(55):
                        state['rendezvous2_done'] = True

    # Collision checks with corridor
    x_min, x_max = sandbox.get_corridor_bounds()
    seeker_x, seeker_y = seeker_pos
    if seeker_x < x_min - 0.02 or seeker_x > x_max + 0.02:
        # Seeker is out of corridor, adjust heading to stay in
        corridor_center = (x_min + (x_max - x_min)/2, seeker_y)
        dx = corridor_center[0] - seeker_x
        dy = corridor_center[1] - seeker_y
        desired_angle = math.atan2(dy, dx)
        # Adjust heading to this direction, within max rotation rate
        current_angle = seeker_angle
        diff = desired_angle - current_angle
        diff = diff % (2 * math.pi)
        if diff > math.pi:
            diff = 2 * math.pi - diff
        if abs(diff) > 0.12:
            if diff > 0:
                new_angle = current_angle + 0.12
            else:
                new_angle = current_angle - 0.12
        else:
            new_angle = current_angle

    # Collision checks with obstacles
    obstacles = sandbox.get_terrain_obstacles()
    for obs in obstacles:
        obs_x, obs_y, obs_width, obs_height = obs
        # Check if seeker is within 0.05 m of obstacle's bounding box
        # Seeker's center is at (seeker_x, seeker_y)
        # Obstacle's bounding box is from (obs_x - obs_width/2, obs_y - obs_height/2) to (obs_x + obs_width/2, obs_y + obs_height/2)
        # Check if seeker is within 0.05 m of the obstacle
        # Check if seeker is within 0.05 m of the obstacle's left, right, top, or bottom
        if (seeker_x - (obs_x - obs_width/2)) < 0.05 or (seeker_x - (obs_x + obs_width/2)) > -0.05:
            if (seeker_y - (obs_y - obs_height/2)) < 0.05 or (seeker_y - (obs_y + obs_height/2)) > -0.05:
                # Collision detected, adjust heading to avoid
                desired_angle = math.atan2(-dy, -dx)
                # Adjust heading to this direction, within max rotation rate
                current_angle = seeker_angle
                diff = desired_angle - current_angle
                diff = diff % (2 * math.pi)
                if diff > math.pi:
                    diff = 2 * math.pi - diff
                if abs(diff) > 0.12:
                    if diff > 0:
                        new_angle = current_angle + 0.12
                    else:
                        new_angle = current_angle - 0.12
                else:
                    new_angle = current_angle

    # Compute new_angle based on desired_angle and current_angle
    current_angle = seeker_angle
    diff = desired_angle - current_angle
    diff = diff % (2 * math.pi)
    if diff > math.pi:
        diff = 2 * math.pi - diff
    if abs(diff) > 0.12:
        if diff > 0:
            new_angle = current_angle + 0.12
        else:
            new_angle = current_angle - 0.12
    else:
        new_angle = current_angle

    # Update state with new angle
    state['seeker_angle'] = new_angle
    state['seeker_pos'] = seeker_pos

    # Cooldown management
    if state['cooldown_remaining'] > 0:
        state['cooldown_remaining'] -= 1
        max_thrust = 40
    else:
        max_thrust = 120

    # Apply thrust
    fx = max_thrust * math.cos(new_angle)
    fy = max_thrust * math.sin(new_angle)
    sandbox.apply_seeker_force(fx, fy)

    # Tracking phase
    if state['rendezvous2_done']:
        dx = target_pos[0] - seeker_pos[0]
        dy = target_pos[1] - seeker_pos[1]
        distance = math.hypot(dx, dy)
        if distance > 8.5:
