            diff = desired_angle - new_angle
            diff = diff % (2 * math.pi)
            if diff > math.pi:
                diff = 2 * math.pi - diff
            if abs(diff) > 0.12:
                if diff > 0:
                    new_angle = new_angle + 0.12
                else:
                    new_angle = new_angle - 0.12

